AssistantMessageToolRequest(name='create', tool_call_id='function-call-a87159b7-aa08-4ef2-9e05-0bce0ebbc996', arguments={'file_text': "document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('contact-form');
    const formStatus = document.getElementById('form-status');

    const fields = {
        name: {
            input: document.getElementById('full-name'),
            error: document.getElementById('name-error'),
            validate: (val) => val.trim() !== '' ? null : 'Error: Full name is required.'
        },
        email: {
            input: document.getElementById('email'),
            error: document.getElementById('email-error'),
            validate: (val) => {
                if (val.trim() === '') return 'Error: Email address is required.';
                const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                if (!emailPattern.test(val)) return 'Error: Enter a valid email like name@example.com.';
                return null;
            }
        },
        phone: {
            input: document.getElementById('phone'),
            error: document.getElementById('phone-error'),
            validate: (val) => {
                if (val.trim() === '') return null; // Optional
                const phonePattern = /^\d{3}-\d{3}-\d{4}$/;
                if (!phonePattern.test(val)) return 'Error: Enter phone number in 123-456-7890 format.';
                return null;
            }
        }
    };

    function validateField(fieldKey) {
        const field = fields[fieldKey];
        const errorMessage = field.validate(field.input.value);

        if (errorMessage) {
            field.error.textContent = errorMessage;
            field.error.hidden = false;
            field.input.setAttribute('aria-invalid', 'true');
            return false;
        } else {
            field.error.textContent = '';
            field.error.hidden = true;
            field.input.removeAttribute('aria-invalid');
            return true;
        }
    }

    // Inline validation on blur
    Object.keys(fields).forEach(key => {
        fields[key].input.addEventListener('blur', () => {
            validateField(key);
        });

        // Clear error as user types if it was previously invalid
        fields[key].input.addEventListener('input', () => {
            if (fields[key].input.getAttribute('aria-invalid') === 'true') {
                validateField(key);
            }
        });
    });

    form.addEventListener('submit', (e) => {
        e.preventDefault();
        formStatus.textContent = '';

        let firstInvalidField = null;
        let isFormValid = true;

        Object.keys(fields).forEach(key => {
            const isValid = validateField(key);
            if (!isValid) {
                isFormValid = false;
                if (!firstInvalidField) {
                    firstInvalidField = fields[key].input;
                }
            }
        });

        if (isFormValid) {
            formStatus.textContent = 'Success! Your message has been sent.';
            formStatus.style.color = '#03dac6';
            form.reset();
            // Clear invalid states
            Object.values(fields).forEach(field => {
                field.input.removeAttribute('aria-invalid');
                field.error.hidden = true;
            });
        } else {
            if (firstInvalidField) {
                firstInvalidField.focus();
            }
            formStatus.textContent = 'Error: Please fix the fields above before submitting.';
            formStatus.style.color = '#cf6679';
        }
    });
});
