<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Support Contact Form</title>
    <style>
        :root {
            --bg-color: #121212;
            --surface-color: #1e1e1e;
            --text-color: #e0e0e0;
            --text-muted: #b0b0b0;
            --primary-color: #bb86fc;
            --error-color: #f28b82; /* Slightly brighter for better contrast on dark */
            --input-bg: #2c2c2c;
            --border-color: #3d3d3d;
            --focus-outline: #03dac6;
        }

        * {
            box-sizing: border-box;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            line-height: 1.5;
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        main {
            width: 100%;
            max-width: 500px;
            padding: 1rem;
        }

        .contact-container {
            background-color: var(--surface-color);
            padding: 2rem;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
        }

        h1 {
            margin-top: 0;
            color: var(--primary-color);
        }

        .form-field {
            margin-bottom: 1.5rem;
        }

        label {
            display: block;
            margin-bottom: 0.5rem;
            font-weight: 600;
        }

        input {
            width: 100%;
            padding: 0.75rem;
            background-color: var(--input-bg);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            color: var(--text-color);
            font-size: 1rem;
        }

        input:focus {
            outline: 2px solid var(--focus-outline);
            outline-offset: 2px;
        }

        input[aria-invalid="true"] {
            border-color: var(--error-color);
        }

        .helper-text {
            font-size: 0.875rem;
            color: var(--text-muted);
            margin: -0.25rem 0 0.5rem;
        }

        .error-message {
            font-size: 0.875rem;
            color: var(--error-color);
            margin-top: 0.25rem;
            font-weight: 500;
        }

        .error-message:not([hidden]) {
            display: block;
        }

        button {
            width: 100%;
            padding: 1rem;
            background-color: var(--primary-color);
            color: #000;
            border: none;
            border-radius: 4px;
            font-size: 1rem;
            font-weight: bold;
            cursor: pointer;
            transition: background-color 0.2s;
        }

        button:hover {
            background-color: #a370f7;
        }

        button:focus {
            outline: 3px solid var(--focus-outline);
            outline-offset: 3px;
        }

        #form-status {
            margin-top: 1rem;
            text-align: center;
            min-height: 1.5em;
        }

        @media (max-width: 400px) {
            .contact-container {
                padding: 1.5rem;
            }
        }
    </style>
</head>
<body>
    <main>
        <section class="contact-container">
            <h1>Contact Support</h1>
            <p>Please fill out the form below and we'll get back to you as soon as possible.</p>
            <p><small><span aria-hidden="true">*</span> indicates a required field</small></p>

            <form id="contact-form" novalidate>
                <div class="form-field">
                    <label for="full-name">Full Name <span aria-hidden="true">*</span></label>
                    <input type="text" id="full-name" name="full-name" required autocomplete="name" aria-describedby="name-error">
                    <p id="name-error" class="error-message" hidden></p>
                </div>

                <div class="form-field">
                    <label for="email">Email Address <span aria-hidden="true">*</span></label>
                    <input type="email" id="email" name="email" required autocomplete="email" aria-describedby="email-error">
                    <p id="email-error" class="error-message" hidden></p>
                </div>

                <div class="form-field">
                    <label for="phone">Phone Number (optional)</label>
                    <p id="phone-helper" class="helper-text">Format: 123-456-7890</p>
                    <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-helper phone-error">
                    <p id="phone-error" class="error-message" hidden></p>
                </div>

                <button type="submit">Send Message</button>
            </form>
            <div id="form-status" aria-live="polite"></div>
        </section>
    </main>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('contact-form');
            const formStatus = document.getElementById('form-status');

            const fields = {
                name: {
                    input: document.getElementById('full-name'),
                    error: document.getElementById('name-error'),
                    validate: (val) => val.trim() !== '' ? null : 'Error: Full name is required.'
                },
                email: {
                    input: document.getElementById('email'),
                    error: document.getElementById('email-error'),
                    validate: (val) => {
                        if (val.trim() === '') return 'Error: Email address is required.';
                        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                        if (!emailPattern.test(val)) return 'Error: Enter a valid email like name@example.com.';
                        return null;
                    }
                },
                phone: {
                    input: document.getElementById('phone'),
                    error: document.getElementById('phone-error'),
                    validate: (val) => {
                        if (val.trim() === '') return null; // Optional
                        const phonePattern = /^\d{3}-\d{3}-\d{4}$/;
                        if (!phonePattern.test(val)) return 'Error: Enter phone number in 123-456-7890 format.';
                        return null;
                    }
                }
            };

            function validateField(fieldKey) {
                const field = fields[fieldKey];
                const errorMessage = field.validate(field.input.value);

                if (errorMessage) {
                    field.error.textContent = errorMessage;
                    field.error.hidden = false;
                    field.input.setAttribute('aria-invalid', 'true');
                    return false;
                } else {
                    field.error.textContent = '';
                    field.error.hidden = true;
                    field.input.removeAttribute('aria-invalid');
                    return true;
                }
            }

            // Inline validation on blur
            Object.keys(fields).forEach(key => {
                fields[key].input.addEventListener('blur', () => {
                    validateField(key);
                });

                // Clear error as user types if it was previously invalid
                fields[key].input.addEventListener('input', () => {
                    if (fields[key].input.getAttribute('aria-invalid') === 'true') {
                        validateField(key);
                    }
                });
            });

            form.addEventListener('submit', (e) => {
                e.preventDefault();
                formStatus.textContent = '';
                formStatus.style.color = '';

                let firstInvalidField = null;
                let isFormValid = true;

                Object.keys(fields).forEach(key => {
                    const isValid = validateField(key);
                    if (!isValid) {
                        isFormValid = false;
                        if (!firstInvalidField) {
                            firstInvalidField = fields[key].input;
                        }
                    }
                });

                if (isFormValid) {
                    formStatus.textContent = 'Success! Your message has been sent.';
                    formStatus.style.color = '#03dac6';
                    form.reset();
                    // Clear invalid states
                    Object.values(fields).forEach(field => {
                        field.input.removeAttribute('aria-invalid');
                        field.error.hidden = true;
                    });
                } else {
                    if (firstInvalidField) {
                        firstInvalidField.focus();
                    }
                    formStatus.textContent = 'Error: Please fix the fields above before submitting.';
                    formStatus.style.color = '#f28b82';
                }
            });
        });
    </script>
</body>
</html>
