                    <p id="name-error" class="error-message" hidden></p>
                </div>

                <div class="form-field">
                    <label for="email">Email Address <span aria-hidden="true">*</span></label>
                    <input type="email" id="email" name="email" required autocomplete="email" aria-describedby="email-error">
                    <p id="email-error" class="error-message" hidden></p>
                </div>

                <div class="form-field">
                    <label for="phone">Phone Number (optional)</label>
                    <p id="phone-helper" class="helper-text">Format: 123-456-7890</p>
                    <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-helper phone-error">
                    <p id="phone-error" class="error-message" hidden></p>
                </div>

                <button type="submit">Send Message</button>
            </form>
            <div id="form-status" aria-live="polite"></div>
        </section>
    </main>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('contact-form');
            const formStatus = document.getElementById('form-status');

            const fields = {
                name: {
                    input: document.getElementById('full-name'),
                    error: document.getElementById('name-error'),
                    validate: (val) => val.trim() !== '' ? null : 'Error: Full name is required.'
                },
                email: {
                    input: document.getElementById('email'),
                    error: document.getElementById('email-error'),
                    validate: (val) => {
                        if (val.trim() === '') return 'Error: Email address is required.';
                        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                        if (!emailPattern.test(val)) return 'Error: Enter a valid email like name@example.com.';
                        return null;
                    }
                },
                phone: {
                    input: document.getElementById('phone'),
                    error: document.getElementById('phone-error'),
                    validate: (val) => {
                        if (val.trim() === '') return null; // Optional
                        const phonePattern = /^\d{3}-\d{3}-\d{4}$/;
                        if (!phonePattern.test(val)) return 'Error: Enter phone number in 123-456-7890 format.';
                        return null;
                    }
                }
            };

            function validateField(fieldKey) {
                const field = fields[fieldKey];
                const errorMessage = field.validate(field.input.value);

                if (errorMessage) {
                    field.error.textContent = errorMessage;
                    field.error.hidden = false;
