                        if (val.trim() === '') return 'Error: Email address is required.';
                        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                        if (!emailPattern.test(val)) return 'Error: Enter a valid email like name@example.com.';
                        return null;
                    }
                },
                phone: {
                    input: document.getElementById('phone'),
                    error: document.getElementById('phone-error'),
                    validate: (val) => {
                        if (val.trim() === '') return null; // Optional
                        const phonePattern = /^\d{3}-\d{3}-\d{4}$/;
                        if (!phonePattern.test(val)) return 'Error: Enter phone number in 123-456-7890 format.';
                        return null;
                    }
                }
            };

